/* \u5C55\u5F00\u5C3A\u5BF8\u7F3A\u7701\uFF08maxSize \u4E0D\u8BBE\uFF09= \u79FB\u9664 inline \u5C3A\u5BF8\u56DE\u843D auto\u2014\u2014auto \u4E0E\u6570\u503C\u9ED8\u8BA4\u4E0D\u53EF\u63D2\u503C
   \uFF08\u77AC\u8DF3\u65E0\u52A8\u753B\uFF09\uFF1Ballow-keywords \u542F\u7528 auto\u2194\u6570\u503C\u8FC7\u6E21\uFF08Chrome 129+/Safari 18.2+\uFF0C
   \u4E0D\u652F\u6301\u6D4F\u89C8\u5668\u6E10\u8FDB\u964D\u7EA7\u77AC\u8DF3\u3001\u4E0D\u52A3\u5316\u2014\u2014\u9700\u8981\u786E\u5B9A\u6027\u52A8\u753B\u8BF7\u663E\u5F0F\u58F0\u660E maxSize\uFF09 */
